import './App.css';
import Gallery from './components/Gallery';
import * as Realm from "realm-web";
const REALM_APP_ID = "keenan-kgkzv"; // e.g. myapp-abcde
const app = new Realm.App({ id: REALM_APP_ID });

function UserDetail({ user }) {
  return (
    <div>
      <h1>Logged in with anonymous id: {user.id}</h1>
    </div>
  );
}
// Create a component that lets an anonymous user log in
function Login({ setUser }) {
  const loginAnonymous = async () => {
    const user = await app.logIn(Realm.Credentials.anonymous());
    setUser(user);
  };
  return <button onClick={loginAnonymous}>Log In</button>;
}

function App() {

  const [user, setUser] = React.useState(app.currentUser);

  return (
    <div className={"flex flex-wrap content-center justify-center h-screen w-screen"}>
      {user ? <UserDetail user={user} /> : <Login setUser={setUser} />}
      <div className="block ">
        <div className={"text-center text-4xl m-8 font-mono italic bold"}>Keenan Cassidy</div>
        <Gallery />
      </div>
    </div>
  );
}

export default App;
